import React, { useState } from "react";
import { Link } from "gatsby";

import { FontAwesomeIcon } from '@fortawesome/react-fontawesome'

const Nav = ({ links }) => {
  const navLinks = links.map((item, index) => (
    <NavLink item={item} key={index} />
  ));

  return (
    <nav className="navbar navbar-expand nav-bg flex-md-column flex-row align-items-start py-3">
      <div className="collapse navbar-collapse m-3">
        <ul className="flex-md-column flex-row navbar-nav w-100 justify-content-between flex-wrap">
          {navLinks}
        </ul>
      </div>
    </nav>
  );
};

const NavLink = ({ item }) => {
  const Item = ({ display, link, icon }) => (
    <Link to={link} className={`nav-link nav-link pl-0`} activeClassName="active">
      <FontAwesomeIcon icon={icon} className="mr-1"/> <span className="d-none d-md-inline-flex">{display}</span>
    </Link>
  );
  const SubItem = ({ display, links, icon }) => {
    const [show, setShow] = useState(false);
    const toggleShow = () => setShow(!show);

    const navLinks = show
      ? links.map((item, index) => <NavLink item={item} key={index} />)
      : null;

    return (
      <ul className="nav-item pl-0">
        <li className={`nav-link nav-link pl-0`}>
          <span
            className="nav-sub"
            onClick={toggleShow}
            onKeyDown={toggleShow}
            role="menuitem"
            tabIndex={0}
          >
            <FontAwesomeIcon icon={icon} /> <span className="d-none d-md-inline-flex">{display}</span>
          </span>
        </li>
        <ul className="flex-md-column flex-row navbar-nav w-100 justify-content-between align-items-end flex-wrap">
          {navLinks}
        </ul>
      </ul>
    );
  };

  return (
    <li className="nav-item">
      {item.link ? (
        <Item display={item.display} link={item.link} icon={item.icon} />
      ) : (
        <SubItem display={item.display} links={item.links} icon={item.icon} />
      )}
    </li>
  );
};

export default Nav;
